#include <iostream>
#include <iomanip>

class LinearEquation {
private:
    double a, b, c, d, e, f;
public:
    LinearEquation(double aVal, double bVal, double cVal, double dVal, double eVal, double fVal)
        : a(aVal), b(bVal), c(cVal), d(dVal), e(eVal), f(fVal) {}

    double getA() const { return a; }
    double getB() const { return b; }
    double getC() const { return c; }
    double getD() const { return d; }
    double getE() const { return e; }
    double getF() const { return f; }

    bool isSolvable() const {
        return (a * d - b * c) != 0.0;
    }

    double getX() const {
        return (e * d - b * f) / (a * d - b * c);
    }

    double getY() const {
        return (a * f - e * c) / (a * d - b * c);
    }
};

int main() {
    // Input: two lines defined by endpoints (x1,y1)-(x2,y2) and (x3,y3)-(x4,y4)
    // (2, 2) to (0, 0) and (0, 2) to (2, 0)
    double x1 = 2.0, y1 = 2.0, x2 = 0.0, y2 = 0.0;
    double x3 = 0.0, y3 = 2.0, x4 = 2.0, y4 = 0.0;

    double a = y1 - y2;
    double b = -(x1 - x2);
    double e = (y1 - y2) * x1 - (x1 - x2) * y1;

    double c = y3 - y4;
    double d = -(x3 - x4);
    double f = (y3 - y4) * x3 - (x3 - x4) * y3;

    LinearEquation eq(a, b, c, d, e, f);
    std::cout << std::fixed << std::setprecision(2);
    if (eq.isSolvable()) {
        std::cout << "Intersecting point: (" << eq.getX() << ", " << eq.getY() << ")" << std::endl;
    } else {
        std::cout << "The equation has no solution." << std::endl;
    }
    return 0;
}

#include <iostream>

class EvenNumber {
private:
    int value;
public:
    EvenNumber() : value(0) {}
    explicit EvenNumber(int val) : value((val % 2 == 0) ? val : val + 1) {}

    int getValue() const {
        return value;
    }

    EvenNumber getNext() const {
        return EvenNumber(value + 2);
    }

    EvenNumber getPrevious() const {
        return EvenNumber(value - 2);
    }
};

int main() {
    EvenNumber n1(16);
    EvenNumber nextN = n1.getNext();
    EvenNumber prevN = n1.getPrevious();

    std::cout << "Current: " << n1.getValue() << std::endl;
    std::cout << "Next: " << nextN.getValue() << std::endl;
    std::cout << "Previous: " << prevN.getValue() << std::endl;
    return 0;
}
